#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve()
{
    int n;
    cin>>n;
    vector<int>a(3*n+1);
    for(int i=1;i<=3*n;i++)cin>>a[i];
    sort(a.begin()+1,a.end());
    reverse(a.begin()+1,a.end());
    vector<int>suf(3*n+2,0);
    for(int i=1;i<=3*n;i++)
    {
        suf[i]=suf[i-1]+a[i];
    }
    // for(int i=1;i<=3*n;i++)cout<<suf[i]<<" ";
    // cout<<'\n';
    auto cook=[&](int a,int b)->int{
       if(3*n<=b || 2*b<4*a || 3*n-3*b+3*a<0)return 0;
       int res=2*suf[a]+suf[2*b-3*a]+3*suf[3*n-b];
       return res;
    };
    auto ter=[&](int a,int l,int r)->int{
        while(r-l>=5)
        {
            int mid=(l+r)/2;
            if(cook(a,mid)<cook(a,mid+1))l=mid;
            else r=mid+1;
        }
        for(int i=l+1;i<r+1;i++)if(cook(a,l)<cook(a,i))l=i;
        return l;
    };
    int ans=0;
    for(int a=0;a<=n;a++)
    {
        int here=cook(a,ter(a,2*a,a+n));
        // cout<<here<<" ";
        // cout<<'\n';
        ans=max(ans,here);
    }
    cout<<ans<<'\n';
    
}
signed main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--)
	{
	    solve();
	}
	
}
